package com.crms.entity;import com.crms.enums.InterviewStatus;import jakarta.persistence.*;import java.time.Instant;@Entity public class Interview{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Application application;private Instant scheduledAt;private String mode,meetingLink,feedback;@Enumerated(EnumType.STRING)private InterviewStatus status=InterviewStatus.SCHEDULED;public Long getId(){return id;}public Application getApplication(){return application;}public void setApplication(Application v){application=v;}public Instant getScheduledAt(){return scheduledAt;}public void setScheduledAt(Instant v){scheduledAt=v;}public String getMode(){return mode;}public void setMode(String v){mode=v;}public String getMeetingLink(){return meetingLink;}public void setMeetingLink(String v){meetingLink=v;}public InterviewStatus getStatus(){return status;}public void setStatus(InterviewStatus v){status=v;}public String getFeedback(){return feedback;}public void setFeedback(String v){feedback=v;}}
